create extension if not exists pgcrypto;
create table if not exists events (id bigint generated always as identity primary key,event_id uuid not null unique,event_name text not null,session_id uuid not null,visitor_id uuid not null,click_id text,site_id text,offer_id text,page_url text,page_path text,page_title text,referrer text,event_time timestamptz not null default now(),attribution jsonb not null default '{}'::jsonb,properties jsonb not null default '{}'::jsonb,user_agent text,ip_hash_source text,created_at timestamptz not null default now());
create index if not exists idx_events_time on events(event_time desc);create index if not exists idx_events_name on events(event_name);create index if not exists idx_events_session on events(session_id);create index if not exists idx_events_click on events(click_id);create index if not exists idx_events_ad_id on events((attribution->>'ad_id'));create index if not exists idx_events_campaign_id on events((attribution->>'campaign_id'));
create table if not exists orders (id bigint generated always as identity primary key,external_order_id text not null unique,provider text not null,status text not null,amount numeric(12,2) not null default 0,currency text not null default 'BRL',click_id text,attribution jsonb not null default '{}'::jsonb,raw_payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_orders_time on orders(occurred_at desc);create index if not exists idx_orders_click on orders(click_id);
create table if not exists ad_metrics (id bigint generated always as identity primary key,metric_date date not null,platform text not null default 'meta',campaign_id text,adset_id text,ad_id text,campaign_name text,adset_name text,ad_name text,spend numeric(12,2) not null default 0,impressions bigint not null default 0,clicks bigint not null default 0,unique(metric_date,platform,ad_id));
alter table events enable row level security;alter table orders enable row level security;alter table ad_metrics enable row level security;
